public protocol ConversationsProtocol: AnyObject, Sendable {

    func beginningDeliveryCursor() async throws  -> String

    func conversationReader(options: ConversationReaderOptions?) async throws  -> ConversationReader

    func createDm(peer: InboxId, options: CreateDmOptions?) async throws  -> Dm

    /**
     * Find or create a DM with an account identity. Hosts present this as a
     * `createDm` overload or union.
     */

    func createGroup(members: [InboxId], options: CreateGroupOptions?) async throws  -> Group

    func createGroupOptimistic(options: CreateGroupOptions?) async throws  -> Group

    /**
     * Create a group from account identities. Hosts present this as a
     * `createGroup` overload or union.
     */

    func deleteMessage(id: MessageId) async throws  -> MessageId

    func deleteMessageLocally(id: MessageId) async throws

    func getById(id: ConversationId) async throws  -> Conversation?

    func getDmByIdentity(identity: PublicIdentity) async throws  -> Dm?

    func getDmByInboxId(peer: InboxId) async throws  -> Dm?

    func getMessageById(id: MessageId) async throws  -> Message?

    func hmacKeys() async throws  -> [String: [HmacKey]]

    func list(options: ListConversationsOptions?) async throws  -> [Conversation]

    func listDms(options: ListConversationsOptions?) async throws  -> [Dm]

    func listGroups(options: ListConversationsOptions?) async throws  -> [Group]

    /**
     * Capture history with kind and consent selection. A replay `from` cursor
     * is invalid because this call captures a new atomic replay boundary.
     */
    func messageHistorySnapshot(limit: UInt32, options: MessageReaderOptions?) async throws  -> MessageHistorySnapshot

    func messageReader(options: MessageReaderOptions?) async throws  -> MessageReader

    func reactToMessage(id: MessageId, reaction: Reaction, options: SendOptions?) async throws  -> MessageId

    func replyToMessage(id: MessageId, content: EncodedContent, options: SendOptions?) async throws  -> MessageId

    /**
     * Host stream ownership.
     */

    func sync() async throws

    func syncAll(consentStates: [ConsentState]?) async throws  -> GroupSyncSummary

}
