public struct FfiConverterTypeDm: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Dm

    public static func lift(_ handle: UInt64) throws -> Dm {
        return Dm(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Dm) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Dm {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Dm, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


