public struct FfiConverterTypeEventReader: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = EventReader

    public static func lift(_ handle: UInt64) throws -> EventReader {
        return EventReader(unsafeFromHandle: handle)
    }

    public static func lower(_ value: EventReader) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EventReader {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: EventReader, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEventReader_lift(_ handle: UInt64) throws -> EventReader {
    return try FfiConverterTypeEventReader.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEventReader_lower(_ value: EventReader) -> UInt64 {
    return FfiConverterTypeEventReader.lower(value)
}






public protocol GroupProtocol: AnyObject, Sendable {

    func addAdmin(inboxId: InboxId) async throws

    func addMembers(members: [InboxId]) async throws  -> MembershipResult

    /**
     * Add members by account identity. Hosts present this as an
     * `addMembers` overload or union.
     */

    func addSuperAdmin(inboxId: InboxId) async throws

    func addedByInboxId()  -> InboxId?

    func countMessages(options: ListMessagesOptions?) async throws  -> UInt64

    func createdAt()  -> Timestamp

    func creatorInboxId()  -> InboxId?

    func debugInfo() async throws  -> ConversationDebugInfo

    func deleteMessage(id: MessageId) async throws  -> MessageId

    func hmacKeys() async throws  -> [HmacKey]

    func id()  -> ConversationId

    func isAdmin(inboxId: InboxId) async throws  -> Bool

    func isCreator()  -> Bool

    func isSuperAdmin(inboxId: InboxId) async throws  -> Bool

    func kind()  -> ConversationKind

    func lastActivityAt(contentTypes: [ContentTypeId]?) async throws  -> Timestamp

    func lastMessage() async throws  -> Message?

    func lastReadTimes() async throws  -> [String: Timestamp]

    func listAdmins() async throws  -> [InboxId]

    func listSuperAdmins() async throws  -> [InboxId]

    /**
     * The value under `key` of the map `field`. An inbox ID key
     * must be lowercase hex; any other spelling fails
     * `InvalidArgument`.
     */
    func mapValue(field: MetadataFieldRef, key: FieldKey) async throws  -> FieldValue?

    func members() async throws  -> [Member]

    func membershipCapabilities() async throws  -> GroupMembershipCapabilities

    func messageHistorySnapshot(limit: UInt32) async throws  -> MessageHistorySnapshot

    func messageReader(options: ConversationMessageReaderOptions?) async throws  -> MessageReader

    func messages(options: ListMessagesOptions?) async throws  -> [Message]

    /**
     * The field named `name`. A well-known field wins over an
     * application field with the same name.
     */
    func metadataField(name: String) async throws  -> MetadataFieldDescriptor?

    /**
     * The conversation's fields in component ID order.
     */
    func metadataFields() async throws  -> [MetadataFieldDescriptor]

    /**
     * The value of `field`, absent when the conversation holds none.
     */
    func metadataValue(field: MetadataFieldRef) async throws  -> MetadataValue?

    /**
     * The values of `fields` in request order, read from one
     * snapshot.
     */
    func metadataValues(fields: [MetadataFieldRef]) async throws  -> [MetadataFieldValue]

    func peerInboxIds() async throws  -> [InboxId]

    func prepareMessage(encoded: EncodedContent, options: SendOptions?) async throws  -> MessageId

    func publishMessage(id: MessageId) async throws

    func publishMessages() async throws

    func removeAdmin(inboxId: InboxId) async throws

    func removeMembers(members: [InboxId]) async throws

    /**
     * Remove members by account identity. Hosts present this as a
     * `removeMembers` overload or union.
     */

    func removeSuperAdmin(inboxId: InboxId) async throws

    func requestRemoval() async throws

    /**
     * Host stream ownership.
     */

    func send(encoded: EncodedContent, options: SendOptions?) async throws  -> MessageId

    func sendActions(actions: Actions, options: SendOptions?) async throws  -> MessageId

    func sendAttachment(attachment: Attachment, options: SendOptions?) async throws  -> MessageId

    func sendIntent(intent: Intent, options: SendOptions?) async throws  -> MessageId

    func sendMarkdown(markdown: String, options: SendOptions?) async throws  -> MessageId

    func sendMultiRemoteAttachment(attachment: MultiRemoteAttachment, options: SendOptions?) async throws  -> MessageId

    func sendReaction(reference: MessageId, referenceInboxId: InboxId?, reaction: Reaction, options: SendOptions?) async throws  -> MessageId

    func sendReadReceipt(options: SendOptions?) async throws  -> MessageId

    func sendRemoteAttachment(attachment: RemoteAttachment, options: SendOptions?) async throws  -> MessageId

    func sendReply(reference: MessageId, referenceInboxId: InboxId?, content: EncodedContent, options: SendOptions?) async throws  -> MessageId

    func sendText(text: String, options: SendOptions?) async throws  -> MessageId

    func sendTransactionReference(reference: TransactionReference, options: SendOptions?) async throws  -> MessageId

    func sendWalletSendCalls(calls: WalletSendCalls, options: SendOptions?) async throws  -> MessageId

    func setNotifications(value: NotificationOverride) async throws

    func state() async throws  -> GroupState

    func sync() async throws

    func topic()  -> String

    func updateAppData(value: String, expected: String?) async throws

    func updateConsentState(state: ConsentState) async throws

    func updateDescription(value: String) async throws

    func updateDisappearingSettings(settings: DisappearingSettings?) async throws

    func updateImageUrl(value: String) async throws

    /**
     * Applies `operation` to `field` in one commit, subject to the
     * field's committed type and policies.
     */
    func updateMetadataField(field: MetadataFieldRef, operation: ComponentMutation) async throws

    func updateName(value: String) async throws

    func updatePermission(kind: PermissionUpdateKind, policy: PermissionPolicy, metadataField: MetadataFieldKind?) async throws

    /**
     * Sets or clears the caller's own user field values in one
     * commit. Nothing is committed when nothing changes.
     */
    func updateUserData(values: [UserFieldUpdate]) async throws

    /**
     * User field values by inbox, read from one snapshot. Absent
     * `fields` selects every user field, and absent `inbox_ids`
     * the current members (the pair in a DM). Every selected
     * inbox has an entry, empty when it holds no selected value.
     * A field whose value does not decode contributes nothing.
     * Inbox IDs must be lowercase hex, the form the result is
     * keyed by; any other spelling fails `InvalidArgument`.
     */
    func userData(fields: [MetadataFieldRef]?, inboxIds: [InboxId]?) async throws  -> [InboxId: [UserFieldValue]]

}
