@_documentation(visibility: private)
#endif
public func FfiConverterTypePreAuthenticate_lift(_ handle: UInt64) throws -> PreAuthenticate {
    return try FfiConverterTypePreAuthenticate.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePreAuthenticate_lower(_ value: PreAuthenticate) -> UInt64 {
    return FfiConverterTypePreAuthenticate.lower(value)
}






