@_documentation(visibility: private)
#endif
public func FfiConverterTypeSigner_lower(_ value: Signer) -> UInt64 {
    return FfiConverterTypeSigner.lower(value)
}






public protocol StorageProtocol: AnyObject, Sendable {

    func delete() async throws

    func path() async throws  -> String?

    func reconnect() async throws

}
open class Storage: StorageProtocol, @unchecked Sendable {
    internal var sdkEventReadGates: SdkEventReadGates?
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_xmtp_sdk_fn_clone_storage(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_xmtp_sdk_fn_free_storage(handle, $0) }
    }




open func delete()async throws   {
    let fileBacked = try await path() != nil
    try Task.checkCancellation()
    if fileBacked { sdkEventReadGates?.stopAll() }
    try await Task.detached { [self] in
    _ =
        try  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_xmtp_sdk_fn_method_storage_delete(
                        self.uniffiCloneHandle()
                )
            },
            pollFunc: ffi_xmtp_sdk_rust_future_poll_void,
            completeFunc: ffi_xmtp_sdk_rust_future_complete_void,
            cancelFunc: ffi_xmtp_sdk_rust_future_cancel_void,
            freeFunc: ffi_xmtp_sdk_rust_future_free_void,
            liftFunc: { $0 },
            errorHandler: FfiConverterTypeXmtpError_lift
        )
    }.value
    try Task.checkCancellation()
}

open func path()async throws  -> String?  {
    return
        try  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_xmtp_sdk_fn_method_storage_path(
                        self.uniffiCloneHandle()
                )
            },
            pollFunc: ffi_xmtp_sdk_rust_future_poll_rust_buffer,
            completeFunc: ffi_xmtp_sdk_rust_future_complete_rust_buffer,
            cancelFunc: ffi_xmtp_sdk_rust_future_cancel_rust_buffer,
            freeFunc: ffi_xmtp_sdk_rust_future_free_rust_buffer,
            liftFunc: FfiConverterOptionString.lift,
            errorHandler: FfiConverterTypeXmtpError_lift
        )
}

open func reconnect()async throws   {
    return
        try  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_xmtp_sdk_fn_method_storage_reconnect(
                        self.uniffiCloneHandle()
                )
            },
            pollFunc: ffi_xmtp_sdk_rust_future_poll_void,
            completeFunc: ffi_xmtp_sdk_rust_future_complete_void,
            cancelFunc: ffi_xmtp_sdk_rust_future_cancel_void,
            freeFunc: ffi_xmtp_sdk_rust_future_free_void,
            liftFunc: { $0 },
            errorHandler: FfiConverterTypeXmtpError_lift
        )
}



}


