    public var value: String
    public var expiresAtSeconds: Int64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(name: String?, value: String, expiresAtSeconds: Int64) {
        self.name = name
        self.value = value
        self.expiresAtSeconds = expiresAtSeconds
    }




}

#if compiler(>=6)
extension Credential: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCredential: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Credential {
        return
            try Credential(
                name: FfiConverterOptionString.read(from: &buf),
                value: FfiConverterString.read(from: &buf),
                expiresAtSeconds: FfiConverterInt64.read(from: &buf)
        )
    }

    public static func write(_ value: Credential, into buf: inout [UInt8]) {
        FfiConverterOptionString.write(value.name, into: &buf)
        FfiConverterString.write(value.value, into: &buf)
        FfiConverterInt64.write(value.expiresAtSeconds, into: &buf)
    }
}


