    return try FfiConverterTypeCredential.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCredential_lower(_ value: Credential) -> RustBuffer {
    return FfiConverterTypeCredential.lower(value)
}


