    case localStorage
    case stagedUnusable
    case connectionBlocked
    case credential
    case backendRejected
    case backendUnavailable
    case targetRejected
    case network
    case insecureUrl
    case blockedAddress
    case tooManyRedirects
    case notFound
    case httpStatus
    case malformed
    case digestMismatch
    case decryptionFailed
    case notAnAttachment
    case deleted





