/**
 * The data of a new attachment. The SDK copies it into its own storage at
 * create, so later changes to the source do not change the attachment.
 *
 * In the browser, `path` names a file in the SDK's OPFS storage pool, and the
 * SDK copies `bytes` to its worker; the caller keeps its buffer.
 *
 * Every host passes `bytes` by copy, so a source holds its size in memory at
 * least twice until create returns. Prefer `path` for data over 1 MiB: the
 * SDK reads a path source in small chunks.
 */

public enum AttachmentSource: Equatable, Hashable {

    case path(path: String, filename: String?, mimeType: String
    )
    case bytes(bytes: Data, filename: String?, mimeType: String
    )





}

#if compiler(>=6)
extension AttachmentSource: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAttachmentSource: FfiConverterRustBuffer {
    typealias SwiftType = AttachmentSource

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AttachmentSource {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .path(path: try FfiConverterString.read(from: &buf), filename: try FfiConverterOptionString.read(from: &buf), mimeType: try FfiConverterString.read(from: &buf)
        )

        case 2: return .bytes(bytes: try FfiConverterData.read(from: &buf), filename: try FfiConverterOptionString.read(from: &buf), mimeType: try FfiConverterString.read(from: &buf)
        )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AttachmentSource, into buf: inout [UInt8]) {
        switch value {


        case let .path(path,filename,mimeType):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            FfiConverterOptionString.write(filename, into: &buf)
            FfiConverterString.write(mimeType, into: &buf)


        case let .bytes(bytes,filename,mimeType):
            writeInt(&buf, Int32(2))
            FfiConverterData.write(bytes, into: &buf)
            FfiConverterOptionString.write(filename, into: &buf)
            FfiConverterString.write(mimeType, into: &buf)

        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAttachmentSource_lift(_ buf: RustBuffer) throws -> AttachmentSource {
    return try FfiConverterTypeAttachmentSource.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAttachmentSource_lower(_ value: AttachmentSource) -> RustBuffer {
    return FfiConverterTypeAttachmentSource.lower(value)
}



