public enum StandardContent: Equatable, Hashable {

    case text(String
    )
    case markdown(String
    )
    case readReceipt
    case reaction(reference: MessageId, referenceInboxId: InboxId?, reaction: Reaction
    )
    case attachment(Attachment
    )
    case remoteAttachment(RemoteAttachment
    )
    case multiRemoteAttachment(MultiRemoteAttachment
    )
    case transactionReference(TransactionReference
    )
    case walletSendCalls(WalletSendCalls
    )
    case actions(Actions
    )
    case intent(Intent
    )
    case reply(reference: MessageId, referenceInboxId: InboxId?, content: EncodedContent
    )
    case groupUpdated(GroupUpdated
    )
    case deleteMessage(messageId: MessageId
    )
    case leaveRequest(LeaveRequest
    )





}

