@_documentation(visibility: private)
#endif
public struct FfiConverterTypeStandardContent: FfiConverterRustBuffer {
    typealias SwiftType = StandardContent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> StandardContent {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .text(try FfiConverterString.read(from: &buf)
        )

        case 2: return .markdown(try FfiConverterString.read(from: &buf)
        )

        case 3: return .readReceipt

        case 4: return .reaction(reference: try FfiConverterTypeMessageId.read(from: &buf), referenceInboxId: try FfiConverterOptionTypeInboxId.read(from: &buf), reaction: try FfiConverterTypeReaction.read(from: &buf)
        )

        case 5: return .attachment(try FfiConverterTypeAttachment.read(from: &buf)
        )

        case 6: return .remoteAttachment(try FfiConverterTypeRemoteAttachment.read(from: &buf)
        )

        case 7: return .multiRemoteAttachment(try FfiConverterTypeMultiRemoteAttachment.read(from: &buf)
        )

        case 8: return .transactionReference(try FfiConverterTypeTransactionReference.read(from: &buf)
        )

        case 9: return .walletSendCalls(try FfiConverterTypeWalletSendCalls.read(from: &buf)
        )

        case 10: return .actions(try FfiConverterTypeActions.read(from: &buf)
        )

        case 11: return .intent(try FfiConverterTypeIntent.read(from: &buf)
        )

        case 12: return .reply(reference: try FfiConverterTypeMessageId.read(from: &buf), referenceInboxId: try FfiConverterOptionTypeInboxId.read(from: &buf), content: try FfiConverterTypeEncodedContent.read(from: &buf)
        )

        case 13: return .groupUpdated(try FfiConverterTypeGroupUpdated.read(from: &buf)
        )

        case 14: return .deleteMessage(messageId: try FfiConverterTypeMessageId.read(from: &buf)
        )

        case 15: return .leaveRequest(try FfiConverterTypeLeaveRequest.read(from: &buf)
        )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: StandardContent, into buf: inout [UInt8]) {
        switch value {


        case let .text(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)


        case let .markdown(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)


        case .readReceipt:
            writeInt(&buf, Int32(3))


        case let .reaction(reference,referenceInboxId,reaction):
            writeInt(&buf, Int32(4))
            FfiConverterTypeMessageId.write(reference, into: &buf)
            FfiConverterOptionTypeInboxId.write(referenceInboxId, into: &buf)
            FfiConverterTypeReaction.write(reaction, into: &buf)


        case let .attachment(v1):
            writeInt(&buf, Int32(5))
            FfiConverterTypeAttachment.write(v1, into: &buf)


        case let .remoteAttachment(v1):
            writeInt(&buf, Int32(6))
            FfiConverterTypeRemoteAttachment.write(v1, into: &buf)


        case let .multiRemoteAttachment(v1):
            writeInt(&buf, Int32(7))
            FfiConverterTypeMultiRemoteAttachment.write(v1, into: &buf)


        case let .transactionReference(v1):
            writeInt(&buf, Int32(8))
            FfiConverterTypeTransactionReference.write(v1, into: &buf)


        case let .walletSendCalls(v1):
            writeInt(&buf, Int32(9))
            FfiConverterTypeWalletSendCalls.write(v1, into: &buf)


        case let .actions(v1):
            writeInt(&buf, Int32(10))
            FfiConverterTypeActions.write(v1, into: &buf)


        case let .intent(v1):
            writeInt(&buf, Int32(11))
            FfiConverterTypeIntent.write(v1, into: &buf)


        case let .reply(reference,referenceInboxId,content):
            writeInt(&buf, Int32(12))
            FfiConverterTypeMessageId.write(reference, into: &buf)
            FfiConverterOptionTypeInboxId.write(referenceInboxId, into: &buf)
            FfiConverterTypeEncodedContent.write(content, into: &buf)


        case let .groupUpdated(v1):
            writeInt(&buf, Int32(13))
            FfiConverterTypeGroupUpdated.write(v1, into: &buf)


        case let .deleteMessage(messageId):
            writeInt(&buf, Int32(14))
            FfiConverterTypeMessageId.write(messageId, into: &buf)


        case let .leaveRequest(v1):
            writeInt(&buf, Int32(15))
            FfiConverterTypeLeaveRequest.write(v1, into: &buf)

        }
    }
}


