 */
public
enum XmtpError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case ClientClosed(ErrorDetails
    )
    case InvalidInput(ErrorDetails
    )
    case StorageLocationRequired(ErrorDetails
    )
    case IdentityNotFound(ErrorDetails
    )
    case StorageBusy(ErrorDetails
    )
    case MigrationUnsupportedSchema(ErrorDetails
    )
    case MigrationFailed(ErrorDetails
    )
    case MigrationRecordRead(ErrorDetails
    )
    case MigrationOutput(ErrorDetails
    )
    case Signer(ErrorDetails
    )
    case Credential(ErrorDetails
    )
    case ConfigurationUnavailable(ErrorDetails
    )
    case ConfigurationInvalid(ErrorDetails
    )
    case BackendMismatch(ErrorDetails
    )
    case ClientVersionTooOld(ErrorDetails
    )
    case AuthRequired(ErrorDetails
    )
    case ChainNotAccepted(ErrorDetails
    )
    case CredentialRejected(ErrorDetails
    )
    case CredentialCallbackFailed(ErrorDetails
    )
    case CallbackFailed(ErrorDetails
    )
    case CredentialExhausted(ErrorDetails
    )
    case CredentialMissing(ErrorDetails
    )
    case PermissionDenied(ErrorDetails
    )
    case InvalidArgument(ErrorDetails
    )
    case OutOfRange(ErrorDetails
    )
    case Unimplemented(ErrorDetails
    )
    case ChannelNotConfigured(ErrorDetails
    )
    case TaskRunnerDisabled(ErrorDetails
    )
    case ResourceExhausted(ErrorDetails
    )
    case RequestTimeout(ErrorDetails
    )
    case NotificationNotFound(ErrorDetails
    )
    case NotificationApi(ErrorDetails
    )
    case NotificationStorage(ErrorDetails
    )
    case NotificationGroup(ErrorDetails
    )
    case RecoveryExhausted(ErrorDetails
    )
    case Storage(ErrorDetails
    )
    case Lagged(ErrorDetails
    )
    case ConsumerOwned(ErrorDetails
    )
    case InvalidCursor(ErrorDetails
    )
    case ForeignCursor(ErrorDetails
    )
    case StorageLocation(ErrorDetails
    )
    case Attachment(ErrorDetails,AttachmentFailure
    )
    /**
     * The identity does not belong to the inbox stored in an `Explicit`
     * database, so the SDK opened no client.
     */
    case IdentityMismatch(ErrorDetails
    )
    case UnknownField(ErrorDetails
    )
    case NotUserField(ErrorDetails
    )
    case DuplicateField(ErrorDetails
    )
    case UnsupportedType(ErrorDetails
    )
    case TypeMismatch(ErrorDetails
    )
    case TypeChanged(ErrorDetails
    )
    /**
     * A host content codec, or its fallback or push hook, failed before the
     * send. The SDK made no publish attempt. The host runtime returns it.
     */
    case CodecEncodeFailed(ErrorDetails
    )
    /**
     * The received type has no decoder. Input error; not retryable.
     */
    case CodecNotFound(ErrorDetails
    )
    /**
     * Content or decompression failed. A core failure is Input; a host
     * decoder failure is Callback. Not retryable. Receive paths keep bytes.
     */
    case CodecDecodeFailed(ErrorDetails
    )
    /**
     * The serialization or type is incomplete or invalid. Input error;
     * not retryable. Receive paths keep the original bytes.
     */
    case MalformedEnvelope(ErrorDetails
    )
    /**
     * The send was published, but the SDK could not confirm its processing.
     * Run the conversation's sync to finish it; do not send it again.
     */
    case PublishedButUnconfirmed(ErrorDetails
    )
    /**
     * The change would make the group larger than its member limit.
     */
    case UserLimitExceeded(ErrorDetails
    )
    /**
     * A binding operation was cancelled before it finished. Partial effects and
     * retry safety depend on the operation. The browser runtime returns it.
     */
    case Cancelled(ErrorDetails
    )
    case Unknown(ErrorDetails
    )






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

